import fs from"fs-extra";import path from"node:path";import{buildPPIconsManifest}from"./ppicons-manifest.js";const START_MARKER="\x3c!-- ppicons:start --\x3e",END_MARKER="\x3c!-- ppicons:end --\x3e",COPILOT_INSTRUCTIONS_FILE=".github/instructions/ppicons.instructions.md",AGENTS_FILE="AGENTS.md";function toWorkspacePath(e,n){return path.join(e,...n.split("/"))}function escapeRegExp(e){return e.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}function hasInstructionFrontmatter(e){return/^---\n[\s\S]*?\n---(?:\n|$)/.test(e)}function getInstructionFrontmatter(e){return["---",'description: "Use when working with ppicons, PPIcons icon components, Prisma PHP/PHPX icons, Caspian icons, icon installation, icon updates, or icon imports."','name: "PPIcons AI Context"',`applyTo: "${[e.project.manifestFile,`${e.project.iconsDirectory}/**`].join(", ")}"`,"---",""].join("\n")}function getPhpUsageExample(e){return["```php","<?php","",`use ${e}\\Search;`,"","?>","","<x-search />",'<x-search class="size-4" />',"```"].join("\n")}function getCaspianUsageExample(e){return["```python",`from ${e} import Search`,"from casp.component_decorator import component, html","","@component","def icon_actions():",'    return html(r"""',"    <div>","        <x-search />",'        <x-search class="size-4" />',"    </div>",'    """)',"```"].join("\n")}function getCatalogResponseExample(){return["```json","{",'  "id": 166531,','  "name": "search",','  "componentName": "Search",','  "svg": "<svg xmlns=\\"http://www.w3.org/2000/svg\\" width=\\"24\\" height=\\"24\\" viewBox=\\"0 0 24 24\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2\\" stroke-linecap=\\"round\\" stroke-linejoin=\\"round\\" class=\\"lucide lucide-search\\"><circle cx=\\"11\\" cy=\\"11\\" r=\\"8\\"/><path d=\\"m21 21-4.3-4.3\\"/></svg>",','  "createdAt": 1774923647142,','  "updatedAt": 1774923647142',"}","```"].join("\n")}function buildManagedBlockContent(e){const{project:n,commands:t,catalogApi:o,usage:r}=e,i=["# PPIcons AI Context","","This project uses `ppicons` to generate reusable icon components.","",`- Framework: ${n.framework}`,`- Framework config file: \`${n.configFile}\``,`- Icons directory: \`${n.iconsDirectory}\``,`- Generated file pattern: \`${r.filePattern}\``,`- Import entry: \`${r.entry}\``,`- Manifest file: \`${n.manifestFile}\``,"",`- Read \`${n.manifestFile}\` under the \`icons\` key when you need the current installed-icon inventory.`,`- Do not duplicate that mutable inventory in agent instructions; \`${n.manifestFile}\` and \`${n.iconsDirectory}\` are the source of truth.`,"","## Checking Whether an Icon Exists","","Resolve an icon name in this order before using or installing it:","",`1. Installed: look for an entry in \`${n.manifestFile}\` \`icons\` whose \`name\` (kebab-case, e.g. \`arrow-right\`) or \`componentName\` (PascalCase, e.g. \`ArrowRight\`) matches, or check that \`${r.filePattern}\` exists in \`${n.iconsDirectory}\`.`,`2. Available but not installed: \`${o.getOne.method} ${o.getOne.urlTemplate}\` (for example \`${o.getOne.exampleUrl}\`) returns the icon JSON object when the name exists in the catalog.`,`3. Unknown or approximate name: \`${o.listAll.method} ${o.listAll.url}\` returns every available icon; search its \`name\` and \`componentName\` fields for the closest match.`,"","Only reference icons that are installed. Install catalog icons with the CLI first; never invent icon names.","","Single icon response example:","",getCatalogResponseExample(),"","## Installing Icons","","When a requested icon does not exist yet, install it with `ppicons` instead of hand-writing a component.","",`- Add one icon: \`${t.addOne}\``,`- Add multiple icons: \`${t.addMany}\``,`- Add the full set: \`${t.addAll}\``,`- Refresh installed icons: \`${t.updateInstalled}\``,"","## Using Installed Icons","","Use HTML-first `x-` icon tags.","","- The tag name is `x-` followed by the kebab-case icon name: `ArrowRight` renders as `<x-arrow-right />`.","- Import the icon component before rendering its tag.",""];return"prisma-php"===n.type?i.push("For Prisma PHP or PHPX templates:","",getPhpUsageExample(r.entry),"",getPhpLocalImportPreference(r.entry)):i.push("For Caspian Python components, routes, and layouts:","",getCaspianUsageExample(r.entry),"","Import every `x-` icon tag from the Python module that authors it. Caspian has no HTML-sidecar or comment import syntax.","",getPythonLocalImportPreference(r.entry)),i.join("\n")}function getPhpLocalImportPreference(e){return["## Local Import Preference","",`For generated or updated PHP imports, prefer grouped namespace imports when two or more icons come from the same \`${e}\` namespace and generated library directory.`,"",`- Use a grouped import when multiple icons are imported from \`${e}\`.`,"- Use a single import when only one icon is needed.","- Do not treat existing separate single imports as wrong unless the task explicitly includes import cleanup.",`- When adding a second or third icon from \`${e}\` to the same file, prefer collapsing those imports into one grouped statement.`,"","Preferred for multiple icons:","","```php","<?php","",`use ${e}\\{ArrowRight, Mail, UserRound};`,"","?>","","<div>",'    <x-mail class="size-4" />','    <x-user-round class="size-4" />','    <x-arrow-right class="size-4" />',"</div>","```","","Fine for one icon:","","```php","<?php","",`use ${e}\\Mail;`,"","?>","```"].join("\n")}function getPythonLocalImportPreference(e){return["## Local Import Preference","",`For generated or updated Python imports, prefer grouped imports when two or more icons come from the same \`${e}\` package.`,"",`- Use a grouped import when multiple icons are imported from \`${e}\`.`,"- Use a single import when only one icon is needed.","- Do not treat existing separate single imports as wrong unless the task explicitly includes import cleanup.",`- When adding a second or third icon from \`${e}\` to the same file, prefer collapsing those imports into one grouped statement.`,"","Preferred for multiple icons:","","```python",`from ${e} import ArrowRight, Mail, UserRound`,"from casp.component_decorator import component, html","","@component","def contact_link():",'    return html(r"""',"    <div>",'        <x-mail class="size-4" />','        <x-user-round class="size-4" />','        <x-arrow-right class="size-4" />',"    </div>",'    """)',"```","","Fine for one icon:","","```python",`from ${e} import Mail`,"```"].join("\n")}function mergeManagedBlock(e,n){const t=new RegExp(`^${escapeRegExp(START_MARKER)}\\s*$[\\s\\S]*?^${escapeRegExp(END_MARKER)}\\s*$`,"m");return t.test(e)?e.replace(t,()=>n).trimEnd()+"\n":0===e.trim().length?`${n}\n`:`${e.trimEnd()}\n\n${n}\n`}async function writePPIconsInstructionFile(e,n,t){const o=[START_MARKER,buildManagedBlockContent(e),END_MARKER].join("\n"),r=await fs.pathExists(n)?await fs.readFile(n,"utf8"):void 0;let i=(r??"").replace(/\r\n/g,"\n");t&&!hasInstructionFrontmatter(i)&&(i=`${getInstructionFrontmatter(e)}${i.trimStart()}`);const s=mergeManagedBlock(i,o);return s!==r&&(await fs.ensureDir(path.dirname(n)),await fs.writeFile(n,s,"utf8")),n}export async function writePPIconsCopilotInstructions(e){const n=await buildPPIconsManifest(e),t=toWorkspacePath(e.projectRoot,COPILOT_INSTRUCTIONS_FILE);return await Promise.all([writePPIconsInstructionFile(n,t,!0),writePPIconsInstructionFile(n,toWorkspacePath(e.projectRoot,"AGENTS.md"),!1)]),t}